/** Injected by Vite `define` in every app/module build (see packages/build). */
declare const __SITE_BASE__: string;
/** Preview builds only: replaces the site name. Empty string = use site.config.json. */
declare const __SITE_TITLE__: string;
/** Preview builds only: prefix for every localStorage key, so preview and real site do not share saved progress. */
declare const __STORAGE_NS__: string;
